using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Animations;
using UnityEngine.Playables;

namespace Politicmon.Animation
{
    /// <summary>
    /// Plays the walk/idle animation of an overworld character in its current direction.
    /// Uses the AnimationClips in Resources/Animations/Characters/&lt;name&gt;/ (generated by
    /// tools/export_unity.py or the "Politicmon/Regenerar animaciones" editor menu). If they are
    /// missing it falls back to swapping the frames in code, so the game always runs.
    /// </summary>
    [RequireComponent(typeof(SpriteRenderer))]
    public class CharacterAnimator : MonoBehaviour
    {
        const float FrameTime = 1f / 12f;

        SpriteRenderer spriteRenderer;
        Animator animator;
        PlayableGraph graph;
        readonly Dictionary<string, AnimationClip> clips = new();
        Sprite[] frames;
        string sheetName;
        string currentClip = "";
        float timer;
        int frameIndex;

        public string Facing { get; private set; } = "down";
        public bool Walking { get; private set; }

        public void Setup(string sheet, string facing)
        {
            sheetName = sheet;
            spriteRenderer = GetComponent<SpriteRenderer>();
            frames = SpriteSheet.CharacterFrames(sheet);
            bool importerSliced = Resources.LoadAll<Sprite>("Sprites/Characters/" + sheet).Length >= 8;
            if (importerSliced)
            {
                foreach (var clip in Resources.LoadAll<AnimationClip>("Animations/Characters/" + sheet))
                    clips[clip.name] = clip;
            }
            if (clips.Count > 0)
            {
                animator = gameObject.AddComponent<Animator>();
                animator.cullingMode = AnimatorCullingMode.AlwaysAnimate;
            }
            SetState(facing, false);
        }

        public void SetState(string facing, bool walking)
        {
            Facing = facing;
            Walking = walking;
            string clipName = $"{sheetName}_{(walking ? "walk" : "idle")}_{facing}";
            if (clipName == currentClip)
                return;
            currentClip = clipName;
            timer = 0f;
            frameIndex = 0;
            ShowFrame();
            if (animator != null && clips.TryGetValue(clipName, out var clip))
            {
                if (graph.IsValid())
                    graph.Destroy();
                AnimationPlayableUtilities.PlayClip(animator, clip, out graph);
                spriteRenderer.flipX = false;
            }
        }

        void Update()
        {
            if (animator != null || !Walking)
                return;
            timer += Time.deltaTime;
            if (timer >= FrameTime * 2)
            {
                timer -= FrameTime * 2;
                frameIndex++;
                ShowFrame();
            }
        }

        /// <summary>Code fallback: alternate stand/step, mirroring every other step when walking up or down.</summary>
        void ShowFrame()
        {
            int dir = Facing switch { "up" => 1, "left" => 2, "right" => 3, _ => 0 };
            bool step = Walking && frameIndex % 2 == 0;
            spriteRenderer.sprite = frames[dir * 2 + (step ? 1 : 0)];
            spriteRenderer.flipX = Walking && step && (frameIndex / 2) % 2 == 1 && dir < 2;
        }

        void OnDestroy()
        {
            if (graph.IsValid())
                graph.Destroy();
        }
    }
}
